        vm.prank(address(this));
        (bool lowSuccess, ) = target.call{value: value}("");
        bool lowRevert = !lowSuccess;

        // Reset contract state for test
        // We need fresh state; redeploy is cleanest but setUp already gives fresh c.
        // The above call already changed balances; we redeploy a fresh c for the sendMoney test.
        C freshC = new C();
        vm.deal(address(freshC), value);

        bool sendReverted;
        vm.prank(address(this));
        try freshC.sendMoney(target, value) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }

        // The property: sendMoney reverts exactly when the low-level call would revert
        assertTrue(sendReverted == lowRevert);
    }
}

