pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 initialDeposit, uint256 ownerBalanceBefore) public {
        // Restrict initial deposit to avoid overflow in balance before deposit
        vm.assume(initialDeposit <= type(uint256).max - address(c).balance);
        vm.assume(ownerBalanceBefore <= type(uint256).max - initialDeposit);

        // Owner is the test contract itself (deployer of C)
        address owner = address(this);

        // Fund the contract by sending ether to its fallback
        vm.deal(address(this), initialDeposit + ownerBalanceBefore);
        (bool success, ) = address(c).call{value: initialDeposit}("");
        require(success, "fallback deposit failed");

        // Record owner's balance before withdrawAll
        uint256 balanceBefore = owner.balance;

        // Call withdrawAll as owner
        c.withdrawAll();

        // Owner's balance after must equal previous balance + initialDeposit
        uint256 balanceAfter = owner.balance;
        assertTrue(balanceAfter == balanceBefore + initialDeposit);
    }
}

